package juloo.keyboard2.suggestions;

import java.io.DataInputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import juloo.cdict.Cdict;

/**
 * Immutable ranked next-word table indexed by Cdict word index, generated by
 * scripts/gen_word_bigrams.py from the AOSP wordlist bigrams. Each head word
 * has up to three continuations, strongest first. Loaded on the decoder
 * worker and validated against the dictionary it will be used with.
 */
public final class WordBigrams
{
  private static final int VERSION = 1;
  static final int FOLLOWERS = 3;
  private static final int NONE = 0xFFFFFF;
  private static final int MAX_ENTRIES = 1 << 20;
  private static final int MAX_SAMPLES = 64;
  private static final int[] NO_FOLLOWERS = new int[0];

  private final int[] _heads;
  private final int[] _followers;

  WordBigrams(int[] heads, int[] followers)
  {
    _heads = heads;
    _followers = followers;
  }

  /** Load [file] and check its sample head words against [dictionary]. */
  public static WordBigrams load(File file, Cdict dictionary)
      throws IOException
  {
    DataInputStream input = new DataInputStream(new FileInputStream(file));
    try
    {
      byte[] magic = new byte[4];
      input.readFully(magic);
      if (!Arrays.equals(magic, "FKWB".getBytes(StandardCharsets.US_ASCII))
          || input.readUnsignedByte() != VERSION)
        throw new IOException("Unsupported word bigram table " + file);
      int entries = input.readInt();
      int samples = input.readUnsignedByte();
      if (entries < 0 || entries > MAX_ENTRIES || samples > MAX_SAMPLES)
        throw new IOException("Word bigram table out of bounds " + file);
      for (int i = 0; i < samples; i++)
      {
        int index = input.readInt();
        byte[] word = new byte[input.readUnsignedByte()];
        input.readFully(word);
        if (dictionary != null && !new String(word, StandardCharsets.UTF_8)
            .equals(word_at(dictionary, index)))
          throw new IOException("Word bigram table does not match the "
              + "dictionary at index " + index);
      }
      int[] heads = new int[entries];
      int[] followers = new int[entries * FOLLOWERS];
      for (int i = 0; i < entries; i++)
      {
        heads[i] = read_u24(input);
        if (i > 0 && heads[i] <= heads[i - 1])
          throw new IOException("Word bigram heads must be sorted " + file);
        for (int j = 0; j < FOLLOWERS; j++)
        {
          int follower = read_u24(input);
          followers[i * FOLLOWERS + j] = follower == NONE ? -1 : follower;
        }
      }
      if (input.read() != -1)
        throw new IOException("Trailing data in word bigram table " + file);
      return new WordBigrams(heads, followers);
    }
    finally { input.close(); }
  }

  /** Continuation indexes for a head index, strongest first. */
  int[] followers(int headIndex)
  {
    int row = Arrays.binarySearch(_heads, headIndex);
    if (headIndex < 0 || row < 0)
      return NO_FOLLOWERS;
    int count = 0;
    while (count < FOLLOWERS && _followers[row * FOLLOWERS + count] >= 0)
      count++;
    return Arrays.copyOfRange(_followers, row * FOLLOWERS,
        row * FOLLOWERS + count);
  }

  private static int read_u24(DataInputStream input) throws IOException
  {
    return (input.readUnsignedByte() << 16) | (input.readUnsignedByte() << 8)
      | input.readUnsignedByte();
  }

  private static String word_at(Cdict dictionary, int index)
  {
    try { return dictionary.word(index); }
    catch (RuntimeException e) { return null; }
  }
}
